  'American Literature I (Pre-1865)',
  'American Literature I (Pre-1865) surveys literature in and about North America from Indigenous oral traditions and colonial encounter through Puritanism, revolution, early national print culture, slavery and abolition, Transcendentalism, American Romanticism, women writers, poetry, and antebellum politics. The course treats literature as an archive of contested nation formation: a record of sovereignty, empire, faith, race, gender, labor, environment, citizenship, and literary experiment. Students practice close reading, historical contextualization, archive use, and scholarly argument.',
  $aml1json${"slug": "american-literature-i-pre-1865", "title": "American Literature I (Pre-1865)", "description": "American Literature I (Pre-1865) surveys literature in and about North America from Indigenous oral traditions and colonial encounter through Puritanism, revolution, early national print culture, slavery and abolition, Transcendentalism, American Romanticism, women writers, poetry, and antebellum politics. The course treats literature as an archive of contested nation formation: a record of sovereignty, empire, faith, race, gender, labor, environment, citizenship, and literary experiment. Students practice close reading, historical contextualization, archive use, and scholarly argument.", "topics": [{"id": "a4f32190-fe64-49e4-93be-d04de59c9303", "type": "topic", "title": "What Counts as Early American Literature: Archives, Orality, Print, and Periodization", "description": "This opening unit challenges students to ask what American literature is before the United States fully exists. The course begins by treating literature as oral performance, manuscript, sermon, political pamphlet, captivity narrative, newspaper, poetry, fiction, and archive.", "children": [{"id": "da979b28-3423-473d-8073-6eb374193bfa", "type": "subtopic", "title": "Periodization and field boundaries", "children": [{"id": "580e848e-eafb-4620-a1fc-ca15558737cb", "type": "concept", "title": "precontact, colonial, revolutionary, early republic, and antebellum frames"}, {"id": "92618aec-d484-46e3-a410-b65b22e8cc9d", "type": "concept", "title": "British America, Spanish borderlands, Caribbean, and Atlantic contexts"}, {"id": "4f30c03a-e927-4409-b092-6d00e267c1d8", "type": "concept", "title": "nation formation and its exclusions"}, {"id": "bfd03349-c9c8-4725-b545-9247b4d4cc81", "type": "concept", "title": "Civil War as threshold rather than endpoint"}], "description": "Students learn why pre-1865 American literature is not just a march toward a national canon, but a contested field shaped by empire, Indigenous sovereignty, slavery, revolution, and print culture."}, {"id": "8750ac9a-3366-4464-8abc-324cf3272d66", "type": "subtopic", "title": "Archives and textual survival", "children": [{"id": "4b9eb4c0-a221-489d-9e9b-e3e2ddc1ad4d", "type": "concept", "title": "manuscript versus print"}, {"id": "cfa28412-2d1c-47c2-829a-eb890a28d2d3", "type": "concept", "title": "editorial mediation"}, {"id": "78aeb286-1d69-48c0-8895-b32237e33407", "type": "concept", "title": "translation and transcription"}, {"id": "42483584-fecf-460b-a9b2-5d6ddc6f2cc7", "type": "concept", "title": "libraries, archives, and digital collections"}], "description": "The point is to understand that syllabi are built from preserved, edited, translated, and institutionalized materials."}, {"id": "2a4c9e1a-d977-4a9e-966b-475986b7d70b", "type": "subtopic", "title": "Methods for reading early texts", "children": [{"id": "f00be588-2f51-44d1-b8bb-cbbd6c757015", "type": "concept", "title": "close reading"}, {"id": "c7181920-566d-439f-9466-fc15714cbceb", "type": "concept", "title": "historicism"}, {"id": "2f5d47a0-b2f5-46a9-8fc8-a5fa5871adf7", "type": "concept", "title": "book history"}, {"id": "d911f97f-316e-4637-ace0-d3817cb2bc30", "type": "concept", "title": "keywords and conceptual history"}], "description": "Students practice close reading while also attending to genre, audience, material form, and historical pressure."}]}, {"id": "0c8d773b-f777-4144-9129-5f1d3a3c52af", "type": "topic", "title": "Indigenous Oral Traditions, Sovereignty, and Contact Narratives", "description": "This unit centers Indigenous presence before and beyond European colonization. Students approach oral traditions, creation narratives, diplomacy, petitions, and contact accounts as complex literary and political forms.", "children": [{"id": "5a068d74-06a5-492a-aa5e-928e318a8156", "type": "subtopic", "title": "Orality, performance, and translation", "children": [{"id": "5a8ddd6b-81c3-4d4b-bf7a-94251fbb45a1", "type": "concept", "title": "creation and emergence narratives"}, {"id": "3aacec3e-b9ef-4e8e-9339-71495cb805c9", "type": "concept", "title": "story cycles and teaching functions"}, {"id": "9309f718-036e-495c-afbb-bba452c6fe80", "type": "concept", "title": "translation politics"}, {"id": "5e4668c4-2991-45d3-b89b-2cf1a869731d", "type": "concept", "title": "performance context and audience"}], "description": "Students learn that oral traditions are not primitive precursors to literature; they are sophisticated knowledge systems shaped by performance, memory, and community."}, {"id": "e5c5977d-3697-44a1-bcf6-d81cd40f3722", "type": "subtopic", "title": "Contact and colonial encounter", "children": [{"id": "f3f327fd-493e-4706-86e3-c986d4b71fac", "type": "concept", "title": "exploration narratives"}, {"id": "c29f4119-0aba-402b-95c4-bf40bea6e435", "type": "concept", "title": "missionary records"}, {"id": "8f4f5159-8e27-48ae-818a-d9234c72f44a", "type": "concept", "title": "ethnographic framing"}, {"id": "f4d372a5-dc36-4673-a167-2721823285f8", "type": "concept", "title": "reciprocity, misunderstanding, and violence"}], "description": "Students examine how European contact accounts construct the Americas and how Indigenous perspectives resist or redirect those claims."}, {"id": "d7c0bc17-f180-420b-8dbe-d27f1a791e97", "type": "subtopic", "title": "Sovereignty and political writing", "children": [{"id": "cf987968-f77a-4287-b0f3-13c97f6839d2", "type": "concept", "title": "treaty rhetoric"}, {"id": "a2f10d3b-bc1e-460c-821f-ed17a53deaea", "type": "concept", "title": "petition and memorial"}, {"id": "e4857de3-a0b7-481d-b12b-87c7dd7d76f9", "type": "concept", "title": "land, law, and kinship"}, {"id": "51183579-7168-4549-8715-ce9f9c425424", "type": "concept", "title": "survivance and continuity"}], "description": "The goal is to read Indigenous speeches, petitions, and diplomacy as literary acts and assertions of nationhood."}]}, {"id": "d72ba4a7-d4ff-45ac-97e7-ea0c5777101d", "type": "topic", "title": "Colonial Encounters, Exploration, and Settlement Writing", "description": "Students study how colonial writing tried to describe, possess, market, and govern the Americas. The emphasis is on rhetoric, empire, religion, labor, and the unstable relationship between observation and ideology.", "children": [{"id": "b494c22d-37eb-470b-822d-5e98b316776d", "type": "subtopic", "title": "Promotional and exploration writing", "children": [{"id": "e695c911-2d2a-45b2-894a-2a33d428caa1", "type": "concept", "title": "wonder and abundance"}, {"id": "4acbb5db-3b7f-4e48-b018-869b28c8881d", "type": "concept", "title": "mapping and naming"}, {"id": "5e975f63-5968-40b7-a031-4e6f47710852", "type": "concept", "title": "colonial propaganda"}, {"id": "918343fe-f943-498a-881a-dfb8ffd1263d", "type": "concept", "title": "resource extraction and labor"}], "description": "Students learn how travel and settlement texts turned land into a project for investors, monarchs, settlers, and readers abroad."}, {"id": "19d79a80-aef4-4346-8d85-da21a819a274", "type": "subtopic", "title": "Mission, conversion, and cultural conflict", "children": [{"id": "b3c93fe7-ae06-49cb-aef5-40f1db071dfe", "type": "concept", "title": "missionary accounts"}, {"id": "2bff7759-2085-4bc0-9cf2-d278db225c64", "type": "concept", "title": "conversion narratives"}, {"id": "cd06017a-7384-4dda-a595-7ad78d5dda9e", "type": "concept", "title": "biblical typology"}, {"id": "31e9e436-9fa9-4d8d-8881-a5013ac570c5", "type": "concept", "title": "cultural translation"}], "description": "Students examine religious language as both spiritual expression and colonial technology."}, {"id": "9073b366-0ea8-4b83-bc77-cd83760ee547", "type": "subtopic", "title": "Colonial genres and authority", "children": [{"id": "d92eb575-7631-4564-8b0b-dbe7bcf6bd4d", "type": "concept", "title": "eyewitness testimony"}, {"id": "803609db-c53d-4cbf-8f35-76bb4f4b3e30", "type": "concept", "title": "letters and journals"}, {"id": "d3171aa1-7c65-4850-b257-477a71c07ce9", "type": "concept", "title": "legal and administrative documents"}, {"id": "6abea238-9a67-40df-b313-1eb6011658c4", "type": "concept", "title": "ethnographic description"}], "description": "Students learn how authors claim credibility when describing unfamiliar places, peoples, and events."}]}, {"id": "a4b5f11a-d30a-4777-9efe-64e04ba9b2fa", "type": "topic", "title": "Puritan Theology, Captivity Narratives, and New England Plain Style", "description": "This unit examines Puritan writing as a literary system grounded in providence, covenant, typology, discipline, and community anxiety. Students read sermons, poetry, spiritual autobiography, and captivity narratives as crafted forms.", "children": [{"id": "75a8e07d-06e7-459c-8d26-26dc5c9f0f6d", "type": "subtopic", "title": "Puritan worldviews and rhetorical form", "children": [{"id": "19f44ce0-ab98-41d0-bc9e-bfe4f697ac40", "type": "concept", "title": "covenant theology"}, {"id": "90d69879-a2b9-4778-b8cb-7df287e53b5d", "type": "concept", "title": "plain style"}, {"id": "b7664201-f62e-43c5-b0ca-e38b740ab2f4", "type": "concept", "title": "typology"}, {"id": "7983eb57-f0ed-44ba-9d9c-c98d1088bbd0", "type": "concept", "title": "sermon structure"}], "description": "Students learn how theology shapes voice, metaphor, plot, and interpretation in seventeenth-century New England writing."}, {"id": "252c8315-25cd-4a93-bddd-698636e7ebf5", "type": "subtopic", "title": "Spiritual autobiography and self-examination", "children": [{"id": "b7be96dd-a3d3-41bd-83ae-89c32f18afdd", "type": "concept", "title": "conversion narrative"}, {"id": "e9c10484-4cd2-49b1-bde5-f4a58d1e38f4", "type": "concept", "title": "diary and meditation"}, {"id": "b9586bf5-b97b-4463-a90c-f9d2ebc1aa0f", "type": "concept", "title": "sin, grace, and assurance"}, {"id": "15bb809c-0080-4d8b-ab30-3c37215cf9c2", "type": "concept", "title": "communal surveillance"}], "description": "Students see how inwardness becomes literary evidence, especially in conversion and devotional writing."}, {"id": "4b34595f-1c3e-49cd-81a3-b338e1e6cd70", "type": "subtopic", "title": "Captivity and border conflict", "children": [{"id": "689760c0-dd4f-43f7-8b41-8caa0a48ba5f", "type": "concept", "title": "Mary Rowlandson and genre conventions"}, {"id": "e8202d1c-944b-4625-b917-34593f3fe8b3", "type": "concept", "title": "violence and providence"}, {"id": "91587140-1f95-46ee-b23c-938d6c650bc7", "type": "concept", "title": "Indigenous representation"}, {"id": "79bb73e3-4963-4e72-b735-45aadb69fce4", "type": "concept", "title": "gendered authorship and authority"}], "description": "Students analyze captivity narratives as religious testimony, colonial propaganda, trauma narrative, and cross-cultural encounter."}]}, {"id": "7f8cdeb5-7a42-404f-a1c9-ee3ed2fa4add", "type": "topic", "title": "Enlightenment, Republicanism, Revolution, and Founding Rhetorics", "description": "Students move from colonial religious frameworks to Enlightenment argument, political persuasion, autobiography, and revolutionary print culture. The unit asks how literature helps imagine citizens, rights, virtue, and nationhood.", "children": [{"id": "df111e41-e262-4d0b-944f-781fc5d8f069", "type": "subtopic", "title": "Franklin and self-making", "children": [{"id": "2ec0d05a-2018-40e5-b0dc-f9ed1dbe4817", "type": "concept", "title": "virtue charts and self-improvement"}, {"id": "4041fd99-06f2-40b8-a217-c3623dcd94c1", "type": "concept", "title": "print capitalism"}, {"id": "873484b6-0164-4499-8aaa-6b66edb5f6c6", "type": "concept", "title": "wit and persona"}, {"id": "7aad1baa-226f-46bb-96b5-bbad94e968b6", "type": "concept", "title": "republican usefulness"}], "description": "Students read autobiography as a genre of self-fashioning, social mobility, discipline, and public performance."}, {"id": "0b31cfd0-df91-4964-9626-937ec2ad1107", "type": "subtopic", "title": "Revolutionary argument and pamphlet culture", "children": [{"id": "6e26bd85-25ae-4f84-9baf-4cacff3a6476", "type": "concept", "title": "Thomas Paine and plain argument"}, {"id": "9d3c6bfe-2fc0-4921-a173-d94f7efd3058", "type": "concept", "title": "Jefferson and declaration rhetoric"}, {"id": "0991bc2a-8226-4bb3-92e5-7373dacdafab", "type": "concept", "title": "natural rights language"}, {"id": "42f190be-0e24-4ba8-8254-442790e469a9", "type": "concept", "title": "public sphere and persuasion"}], "description": "Students learn how political prose mobilizes readers through logic, emotion, urgency, and shared grievance."}, {"id": "335df844-c93c-49d1-9828-090850276a79", "type": "subtopic", "title": "Contradictions of liberty", "children": [{"id": "628cd968-3c60-4167-af06-3fb76c449a80", "type": "concept", "title": "enslavement and freedom rhetoric"}, {"id": "0ebdb61c-2ec8-464e-935a-e9085502691e", "type": "concept", "title": "women and republican motherhood"}, {"id": "71d9a5af-4ce2-4561-981a-2056122e17c3", "type": "concept", "title": "Indigenous diplomacy"}, {"id": "be6d20e4-ad51-4250-a854-56cb88d086ae", "type": "concept", "title": "property, consent, and exclusion"}], "description": "Students confront how revolutionary ideals coexist with slavery, dispossession, gender hierarchy, and restricted citizenship."}]}, {"id": "7f0bc419-a21a-4714-8097-0d3d6f612e3b", "type": "topic", "title": "Early Republic Print Culture, Sentimental Fiction, and Gothic Beginnings", "description": "This unit treats the early republic as an experimental literary marketplace. Students study novels, newspapers, magazines, seduction plots, and gothic forms as sites where readers debated morality, gender, class, and national identity.", "children": [{"id": "6e7c507d-0d4e-4328-bd2f-d88c784c884e", "type": "subtopic", "title": "Print culture and readership", "children": [{"id": "ebe388d3-0e4a-4b75-b404-a8c5b24a2597", "type": "concept", "title": "newspapers and magazines"}, {"id": "7a8cd400-caf7-4137-9926-2e259620bd42", "type": "concept", "title": "subscription and circulation"}, {"id": "91894202-6430-4b37-8056-9d87335845bd", "type": "concept", "title": "anonymity and pseudonyms"}, {"id": "a02f6a0d-87ae-4ee1-b99e-462fd5ac290b", "type": "concept", "title": "reading publics"}], "description": "Students learn how expanding print networks shaped literary form and public debate."}, {"id": "5de4cc7f-a777-426e-b2fe-12fa0bc15e0e", "type": "subtopic", "title": "Sentimental and seduction fiction", "children": [{"id": "9ce7670a-093c-4df8-ab7d-3127197a5b08", "type": "concept", "title": "The Coquette and Charlotte Temple traditions"}, {"id": "ba43b509-8377-43bb-96a4-1f835b427dee", "type": "concept", "title": "epistolary form"}, {"id": "aff1ef78-e65d-482e-ae31-8ed2b017fec5", "type": "concept", "title": "female readership"}, {"id": "e24f0185-8674-4f70-97da-b57191fa28b0", "type": "concept", "title": "moral pedagogy and pleasure"}], "description": "Students examine how early novels stage questions of virtue, consent, education, reputation, and social control."}, {"id": "5ab6b38a-3c81-49c2-b48f-80cccb767533", "type": "subtopic", "title": "American gothic", "children": [{"id": "8477135a-2022-4ced-922c-964b65de6a7d", "type": "concept", "title": "Charles Brockden Brown"}, {"id": "93e2553a-1bb3-4de1-9821-c2b4faa16696", "type": "concept", "title": "haunting and paranoia"}, {"id": "4008ad91-f053-46b8-8761-d9eda16058ea", "type": "concept", "title": "frontier and city spaces"}, {"id": "78392c64-07af-4690-a419-7d2ae02ea8e0", "type": "concept", "title": "madness, reason, and contagion"}], "description": "Students read gothic fiction as a way of representing national anxiety, violence, secrecy, and unstable authority."}]}, {"id": "b54b5da6-911a-456e-ab23-163a77bb3513", "type": "topic", "title": "Slavery, Abolition, and Black Atlantic Writing", "description": "Students study slavery not as background but as a central condition of early American literary production. The unit foregrounds Black authorship, testimony, abolitionist print networks, and Atlantic circuits of freedom and captivity.", "children": [{"id": "edca53d5-0bf4-418f-bc3c-0ea6b33f753d", "type": "subtopic", "title": "Slave narratives as literary and political form", "children": [{"id": "a38a4b7a-df42-4188-83d6-c5fc1b37145c", "type": "concept", "title": "Frederick Douglass"}, {"id": "f72cd79d-f1ad-4661-ada5-7d6adb3b940d", "type": "concept", "title": "Harriet Jacobs"}, {"id": "312759df-49ff-4f19-9e33-d094bd725ced", "type": "concept", "title": "authenticating documents"}, {"id": "b0228859-0e1e-4e40-bc6d-43f448d9dd12", "type": "concept", "title": "scene of literacy"}], "description": "Students learn how narrators craft authority under hostile conditions and turn life writing into abolitionist evidence."}, {"id": "2686469e-81d5-4dfe-9c6b-65d8ed9c7d51", "type": "subtopic", "title": "Black Atlantic voices", "children": [{"id": "d9bc817e-f66b-47a8-92e4-bde85ebe82bb", "type": "concept", "title": "Phillis Wheatley"}, {"id": "55b25e11-a664-4a89-a310-7048120c9792", "type": "concept", "title": "Olaudah Equiano"}, {"id": "2ac2ebf5-8664-482c-bf78-c73a0e12077f", "type": "concept", "title": "religion and freedom"}, {"id": "d068bb53-6c72-4491-907b-07e221224ad3", "type": "concept", "title": "mobility and diaspora"}], "description": "Students place early African American writing in transatlantic contexts of enslavement, conversion, commerce, and revolution."}, {"id": "35ea030a-b940-4858-a5c2-12205f08befb", "type": "subtopic", "title": "Abolitionist media and rhetoric", "children": [{"id": "d06da0ef-8e9c-4a7f-9969-a6b10cab9974", "type": "concept", "title": "moral suasion"}, {"id": "0ffb7793-f4a9-4bd4-a06d-10c789b0973a", "type": "concept", "title": "visual and print campaigns"}, {"id": "4574d8a9-24df-4ff2-ade4-6435b2203d08", "type": "concept", "title": "women abolitionists"}, {"id": "4580f21d-a1e9-4e04-80ef-2d5e260589af", "type": "concept", "title": "risk, censorship, and violence"}], "description": "Students examine how antislavery writing circulates through speeches, newspapers, poetry, petitions, and reform organizations."}]}, {"id": "5c2ba99d-4af0-444f-9369-f70699ef7dd1", "type": "topic", "title": "Native American and African American Oratory, Petition, and Political Voice", "description": "This unit extends the course beyond canonical genres by treating public address, petitions, memorials, and political documents as literary acts. Students learn how marginalized communities used available forms to speak against law, violence, and exclusion.", "children": [{"id": "73d0476e-a598-4e8e-b382-558ffd306cc9", "type": "subtopic", "title": "Oratory and public address", "children": [{"id": "9426a587-c21b-43ac-bdfc-d4f4899fa9bf", "type": "concept", "title": "delivery and transcription"}, {"id": "024c2989-78d7-4812-9217-0d9263e27327", "type": "concept", "title": "ethos and collective voice"}, {"id": "b07f5ce5-1b64-40a9-a68d-af817ce8ed16", "type": "concept", "title": "mourning and protest"}, {"id": "6595449d-6f71-4f7f-98d7-6a1311edf141", "type": "concept", "title": "religious and civic registers"}], "description": "Students learn to read speeches as performances shaped by occasion, audience, transcription, and power."}, {"id": "a22eb932-eb38-484e-81b6-f3a875277093", "type": "subtopic", "title": "Petition and legal language", "children": [{"id": "98c7b550-3b38-4f44-aa9d-5f8dcb5c7b23", "type": "concept", "title": "petition structure"}, {"id": "fef3cce1-f88b-4b86-b4bf-261fb4dd96b1", "type": "concept", "title": "rights language"}, {"id": "122ab17b-53d9-4c93-a234-a6eee3600cea", "type": "concept", "title": "citizenship claims"}, {"id": "5608b4c2-e4e6-430f-a5e2-c2c9afa22b23", "type": "concept", "title": "archives of dissent"}], "description": "Students study petition as a genre that converts grievance into public record and political claim."}, {"id": "ca0a7d7c-43c3-4d9d-9c7b-c3fe32ff50d4", "type": "subtopic", "title": "Coalition, reform, and counterpublics", "children": [{"id": "0a475fd8-177f-458b-9584-f24e45e7565f", "type": "concept", "title": "Black conventions"}, {"id": "e6cb0dfa-5f05-4309-be1e-acfb0be867c2", "type": "concept", "title": "Indigenous diplomacy"}, {"id": "e6bc16e8-0ae8-4714-8411-b527f37f21b4", "type": "concept", "title": "antislavery networks"}, {"id": "16a221d0-0c9d-42cd-b867-d84b8733ce58", "type": "concept", "title": "newspaper counterpublics"}], "description": "Students explore how writers build communities of readers outside dominant institutions."}]}, {"id": "1e44be66-6d35-4185-b087-48dad93abe86", "type": "topic", "title": "Transcendentalism, Reform, and Environmental Thought", "description": "Students study Transcendentalism as philosophy, literary style, reform culture, and environmental imagination. The unit links Emerson and Thoreau to abolition, education, women’s rights, labor, and nature writing.", "children": [{"id": "a633be48-33cc-49a2-b07c-cd2e89416963", "type": "subtopic", "title": "Emersonian self-reliance and intellectual independence", "children": [{"id": "dc65a18d-3441-4823-85dd-c3a84b9a9376", "type": "concept", "title": "self-reliance"}, {"id": "baa5a1ce-5f5d-47a3-acdb-32d5d000cbad", "type": "concept", "title": "intuition and idealism"}, {"id": "1544f427-e59c-4179-b6c5-be6c6b9f8ef1", "type": "concept", "title": "lecture culture"}, {"id": "25d3a5bd-a806-4120-99c9-2d03b1cf6a2a", "type": "concept", "title": "aphorism and prose style"}], "description": "Students learn how the essay form becomes a vehicle for philosophical provocation and literary experiment."}, {"id": "c29b0081-04a6-4be5-a553-ffc9c32189b6", "type": "subtopic", "title": "Thoreau, nature, and civil disobedience", "children": [{"id": "1f977707-7afb-4a0e-ab33-91789ae25f94", "type": "concept", "title": "Walden and experiment"}, {"id": "de1ab679-497e-4fb2-a51e-617aaa02f7d7", "type": "concept", "title": "walking and observation"}, {"id": "32d9a5ca-8c07-4d4d-a4a2-bdc64caf947a", "type": "concept", "title": "civil disobedience"}, {"id": "2317793a-7433-4f0c-95ca-b95c92df9faa", "type": "concept", "title": "environmental humanities"}], "description": "Students read Thoreau across ecology, economics, ethics, and resistance."}, {"id": "9de310a1-f8e2-4d9b-a661-5a67878a57be", "type": "subtopic", "title": "Reform movements and utopian experiments", "children": [{"id": "7fdf8d6b-368c-44ff-ae35-8401812f4711", "type": "concept", "title": "Brook Farm"}, {"id": "e5f5a5ed-2b36-461a-86c4-e046ecdce608", "type": "concept", "title": "abolition"}, {"id": "c31f18c2-c2a7-4aad-bdaf-bb717b43bf85", "type": "concept", "title": "education reform"}, {"id": "3ef6c438-1b26-4c49-a635-76a0ba152d0f", "type": "concept", "title": "women's rights and labor reform"}], "description": "Students situate Transcendentalist writing in a broader antebellum reform landscape."}]}, {"id": "aba6ae0d-7e11-41a0-af4f-cbe96c5ec717", "type": "topic", "title": "American Romanticism: Poe, Hawthorne, Melville, and Dark National Allegory", "description": "This unit shows how American Romanticism explores obsession, sin, ambiguity, perception, violence, and national guilt. Students learn to connect formal intensity with historical unease.", "children": [{"id": "42f13403-bf83-4c29-900e-946cd96b5304", "type": "subtopic", "title": "Poe and the aesthetics of effect", "children": [{"id": "1d35bd6c-0bba-49eb-8a25-c965db71940d", "type": "concept", "title": "single effect"}, {"id": "d3a376c4-aa21-4501-87d4-e3d4503c9a65", "type": "concept", "title": "unreliable narration"}, {"id": "8324e86b-1bd5-4a60-963c-2c9125fe62c2", "type": "concept", "title": "detective fiction"}, {"id": "6ccd5f27-c51f-4f17-8b5e-9993e6f41e9e", "type": "concept", "title": "sound and lyric intensity"}], "description": "Students examine short fiction and poetry as engineered experiences of fear, compression, rhythm, and unreliability."}, {"id": "14153080-ec75-4dc7-b666-1df71012b3df", "type": "subtopic", "title": "Hawthorne and historical allegory", "children": [{"id": "61f4ac77-4219-4cdd-8c7d-7d89e3767a78", "type": "concept", "title": "romance versus novel"}, {"id": "bab58477-6dc0-42ff-aa27-8ed473624170", "type": "concept", "title": "symbol and ambiguity"}, {"id": "487e9c60-5048-4773-a4a1-1c80a0393474", "type": "concept", "title": "The Scarlet Letter"}, {"id": "0a40705c-1f95-4054-85e3-3bf514654547", "type": "concept", "title": "ancestry and guilt"}], "description": "Students learn how romance allows Hawthorne to revisit Puritanism, secrecy, gender, and moral ambiguity."}, {"id": "e7a446f6-f9fe-4e21-b438-594f99e60f3a", "type": "subtopic", "title": "Melville and epistemological crisis", "children": [{"id": "7841ebe7-c721-4989-9d0a-2a5de6e4d6c4", "type": "concept", "title": "Moby-Dick and encyclopedic form"}, {"id": "49524f4b-25ca-47e0-abd4-61a5070d80df", "type": "concept", "title": "Bartleby and labor"}, {"id": "4509d756-79e9-4638-b6f4-3f3f3aee2fe1", "type": "concept", "title": "race and empire at sea"}, {"id": "94b6d0ae-7435-4d42-9d94-995eaa6ae395", "type": "concept", "title": "irony and narrative instability"}], "description": "Students study Melville’s fiction as a field of philosophical, political, racial, and formal disturbance."}]}, {"id": "7e8695f6-10ff-42e9-bbff-53fc14145ddd", "type": "topic", "title": "American Renaissance, Canon Formation, and Its Revisions", "description": "Students learn why the American Renaissance became a powerful but contested category. The unit treats canon formation as a historical process, then asks how revised canons change the story of American literature.", "children": [{"id": "3308953d-62d6-496a-8e25-81b454bd34b5", "type": "subtopic", "title": "The classic American Renaissance", "children": [{"id": "2b0ae478-441e-4488-9840-81aef56c5ba6", "type": "concept", "title": "Emerson, Thoreau, Hawthorne, Melville, Whitman"}, {"id": "52a0b456-c58a-4c35-b288-78bf1c34d316", "type": "concept", "title": "F. O. Matthiessen and critical history"}, {"id": "9c25a53e-0f7f-4864-9973-5d4146ee25fd", "type": "concept", "title": "democracy and individualism"}, {"id": "4ab65c01-76da-494a-b7bd-3d571c7b1967", "type": "concept", "title": "symbolic depth and national literature"}], "description": "Students identify the authors, myths, and critical arguments that shaped the mid-nineteenth-century canon."}, {"id": "ec2d3d76-a4f3-4599-bccf-8a85d4f0e0ab", "type": "subtopic", "title": "Canon critique and recovery", "children": [{"id": "b5f6916f-1645-4873-aadf-f359b9cd9a28", "type": "concept", "title": "recovery scholarship"}, {"id": "7a540998-f8b3-4f45-adf3-97a252141630", "type": "concept", "title": "anthology politics"}, {"id": "814a6517-a643-42b6-83e5-acc46b80be28", "type": "concept", "title": "genre hierarchy"}, {"id": "441760ad-3688-4c12-9459-a87456201648", "type": "concept", "title": "archives and institutional power"}], "description": "Students learn how feminist, Black, Indigenous, and multiethnic scholarship changed the field."}, {"id": "54620252-a81a-417b-91d0-fcf3ec826499", "type": "subtopic", "title": "Comparative canon building", "children": [{"id": "214af8e0-f74f-4afb-8c11-83d78423a5b0", "type": "concept", "title": "counter-canon exercises"}, {"id": "5bc0916c-2d27-426a-8fdc-4c71310e9756", "type": "concept", "title": "paired readings"}, {"id": "f2f779a4-c1b1-40ab-a3a5-3c5cf7fc3051", "type": "concept", "title": "syllabus design as argument"}, {"id": "3a49a183-c505-47d7-86b2-36e97025717a", "type": "concept", "title": "field keywords"}], "description": "Students practice building alternative literary maps around themes such as slavery, sovereignty, gender, print, ecology, and empire."}]}, {"id": "5443ada6-6c24-4499-8501-9d593382927f", "type": "topic", "title": "Women Writers, Domestic Fiction, Poetry, and Public Authorship", "description": "This unit centers women’s authorship as a major force in early American literature. Students study domestic fiction, poetry, reform writing, letters, and public literary careers.", "children": [{"id": "bc5002a2-a1a9-485c-be98-480090b96bad", "type": "subtopic", "title": "Domestic and sentimental fiction", "children": [{"id": "ff1a63f5-694e-4f4b-aff8-546a9ca58d40", "type": "concept", "title": "Harriet Beecher Stowe"}, {"id": "3bdc4624-d96a-4a0a-a381-c7ddef524e9d", "type": "concept", "title": "Susan Warner and domestic ideology"}, {"id": "c24520ef-6ed2-40a8-bf02-3fac3bddad30", "type": "concept", "title": "sentiment and reform"}, {"id": "c6356386-43e4-4d3f-bec4-ba457a235402", "type": "concept", "title": "home, market, and nation"}], "description": "Students read domestic writing as a serious site of power, pedagogy, race, labor, and national imagination."}, {"id": "51291f52-41ea-476e-aea7-ea873265c10c", "type": "subtopic", "title": "Women poets and literary authority", "children": [{"id": "99a018ee-94f6-4c8e-a9fc-a2e420251e6b", "type": "concept", "title": "Anne Bradstreet"}, {"id": "569acf79-94f2-4add-8e22-e34d478d9868", "type": "concept", "title": "Phillis Wheatley"}, {"id": "f6ff0203-034b-49a2-9196-7a450a7c2cab", "type": "concept", "title": "Emily Dickinson"}, {"id": "20b2abf8-bc27-42b8-b215-b733e5a36d5f", "type": "concept", "title": "manuscript and circulation"}], "description": "Students examine how women poets negotiate publication, privacy, religion, friendship, and formal innovation."}, {"id": "916f4fe2-381c-4b8d-a595-691c37c04fb7", "type": "subtopic", "title": "Gender, authorship, and public reform", "children": [{"id": "6f64c873-9f28-4936-adbd-4539c86ae081", "type": "concept", "title": "abolitionist women"}, {"id": "c94923fd-faf8-4b72-bfd3-96b59832ab09", "type": "concept", "title": "women's rights conventions"}, {"id": "196abf30-467b-4897-bb2a-d24e4d9ad672", "type": "concept", "title": "editorship and periodicals"}, {"id": "5d22ebce-9c86-482e-996a-0c5b7d3c663b", "type": "concept", "title": "respectability and resistance"}], "description": "Students study how women used print and speech to enter debates about slavery, education, labor, and rights."}]}, {"id": "c255e612-2a5a-4f13-a174-bd268b3d76f6", "type": "topic", "title": "Whitman, Dickinson, and the Poetics of Democracy, Selfhood, and Form", "description": "Students close-read two writers whose experiments transformed American poetry. The unit pairs public expansiveness and private compression, asking how form creates ideas of body, nation, faith, death, and self.", "children": [{"id": "0c5aa3f7-09cf-4ec4-a00e-1686f1cb2601", "type": "subtopic", "title": "Whitman and democratic poetics", "children": [{"id": "49338ad7-8d4c-4cd6-8cb2-d99a5324632c", "type": "concept", "title": "Leaves of Grass editions"}, {"id": "ef867923-4178-407e-b2d8-35acc742b7f7", "type": "concept", "title": "catalogue and line"}, {"id": "57a09270-d8b9-480a-8840-d13bbb296332", "type": "concept", "title": "body and sexuality"}, {"id": "27a999d0-333b-4b62-bd80-31d1726d9889", "type": "concept", "title": "war, democracy, and voice"}], "description": "Students examine free verse, catalogues, bodily presence, and the imagined relation between poet and nation."}, {"id": "6b0b46a6-610a-4108-b0ee-ce43e9c5cf80", "type": "subtopic", "title": "Dickinson and lyric compression", "children": [{"id": "61d13215-c6d7-4e52-a0f9-2f9b0505128f", "type": "concept", "title": "manuscript fascicles"}, {"id": "edb9d2f1-295e-4fce-90e6-c66342867bc5", "type": "concept", "title": "meter and hymn form"}, {"id": "5877fc09-00bd-4dfd-9238-c80ad0180318", "type": "concept", "title": "death and belief"}, {"id": "74910bae-9ea7-4854-bd11-e55b146765b2", "type": "concept", "title": "variant words and editorial history"}], "description": "Students learn how Dickinson’s manuscripts, variants, dashes, slant rhyme, and syntax challenge ordinary reading habits."}, {"id": "f98f357c-abae-454b-ab86-f5332626db08", "type": "subtopic", "title": "Comparative poetic method", "children": [{"id": "5f9b27fa-5f58-4695-9c21-fbaa2940995a", "type": "concept", "title": "lineation and stanza"}, {"id": "043d461f-c983-4060-bc3b-116ff7b82c33", "type": "concept", "title": "address and speaker"}, {"id": "8cd3d774-fa2b-46ce-b6f5-b67d116daa50", "type": "concept", "title": "publication history"}, {"id": "742f1d66-b348-48a4-b022-d8b1628a5d6f", "type": "concept", "title": "democracy, privacy, and experiment"}], "description": "Students use Whitman and Dickinson to develop high-level close reading of form as argument."}]}, {"id": "bf8b1c13-88b3-491d-941d-52b2be171a36", "type": "topic", "title": "Antebellum Literature, Sectional Crisis, and Civil War Thresholds", "description": "This unit brings the course to the edge of the Civil War by connecting literary form to sectional conflict, reform urgency, racial violence, and competing ideas of union and freedom.", "children": [{"id": "8844252d-bcdc-44de-8247-c55e011b5d77", "type": "subtopic", "title": "Literature and sectional politics", "children": [{"id": "92a74f88-3ad2-4dbd-934f-c258f61b656f", "type": "concept", "title": "Fugitive Slave Act"}, {"id": "71c3fe18-251f-47b7-b045-b7dd0ab0bfdd", "type": "concept", "title": "Kansas-Nebraska conflict"}, {"id": "ad6e0ff1-a9e2-446e-aec9-d375eefe9e1f", "type": "concept", "title": "proslavery and antislavery rhetoric"}, {"id": "9013b361-8c99-449c-890d-bec907a47a83", "type": "concept", "title": "regional print cultures"}], "description": "Students learn how fiction, poetry, speeches, and newspapers participated in debates over slavery, expansion, and union."}, {"id": "f6911eeb-b7f0-4f5c-8c8f-715cbd70e893", "type": "subtopic", "title": "Civil War thresholds", "children": [{"id": "edf6cfbf-b26a-4037-a217-cfb1cbe4a5ad", "type": "concept", "title": "war poetry beginnings"}, {"id": "ac5b78a0-d116-4688-9605-8bd65432c16b", "type": "concept", "title": "Lincoln and public prose"}, {"id": "725546c5-b403-4a3c-897d-e5ced8cf3151", "type": "concept", "title": "martyrdom and sacrifice"}, {"id": "eba65ba4-8cbf-4f96-bd38-330b1cf37749", "type": "concept", "title": "memory and reconciliation myths"}], "description": "Students trace how prewar literary forms anticipate wartime memory, mourning, and national fracture."}, {"id": "103178d1-0142-42d4-b79f-4c5e957458c8", "type": "subtopic", "title": "Citizenship, race, and futurity", "children": [{"id": "a4bcd69d-e74c-483b-a290-745dcbfded60", "type": "concept", "title": "Dred Scott and legal personhood"}, {"id": "25843b88-7970-4900-9bf8-56b323842e1a", "type": "concept", "title": "Black citizenship claims"}, {"id": "a100df2e-c916-40f4-86f1-e86d606e5cb4", "type": "concept", "title": "Indigenous removal and survival"}, {"id": "73891c3c-6d20-463e-a752-3fc154ba41e9", "type": "concept", "title": "gender and political belonging"}], "description": "Students ask whose futures antebellum literature imagined, denied, or fought to create."}]}, {"id": "a4c85a95-b453-43e4-8a6a-c379bd9ba276", "type": "topic", "title": "Research Methods: Close Reading, Historicism, Archives, and Scholarly Argument", "description": "The final methodological unit gives students the tools to turn literary interest into a rigorous argument. It draws from undergraduate literary study and graduate English methods: bibliography, databases, archives, theory, and ethical citation.", "children": [{"id": "3572d71d-a5be-4bc4-94c2-dc9afadca562", "type": "subtopic", "title": "Close reading and historical evidence", "children": [{"id": "28a62163-366b-4fee-8859-447e6cbf3bbe", "type": "concept", "title": "formal evidence"}, {"id": "8be99f1d-77d4-4339-983d-88a5865d9042", "type": "concept", "title": "historical context"}, {"id": "d6f1ef89-3328-4055-aee1-522f32a4310d", "type": "concept", "title": "genre conventions"}, {"id": "41af3a59-d3da-43fe-b8e3-c0f9828359ad", "type": "concept", "title": "claim-evidence reasoning"}], "description": "Students learn to connect textual details to historically grounded claims without reducing literature to mere illustration."}, {"id": "3882167f-a735-47c5-9ba8-5327bb23d0d6", "type": "subtopic", "title": "Research process and bibliography", "children": [{"id": "f114c10d-14cc-410a-9f85-1ea767a16bb0", "type": "concept", "title": "MLA International Bibliography"}, {"id": "fef391f2-77ee-4b4f-82b6-de3106cd825a", "type": "concept", "title": "JSTOR and Project MUSE"}, {"id": "0e6dd311-fad5-4974-b781-0ad7f33bb9b5", "type": "concept", "title": "annotated bibliography"}, {"id": "5cad3b40-4800-4a8b-89a8-3c92e9c911dc", "type": "concept", "title": "secondary source synthesis"}], "description": "Students practice finding, evaluating, and integrating scholarship in a way that strengthens interpretation."}, {"id": "b2b3684b-45bb-4cf7-9ca3-ed6645b4bab8", "type": "subtopic", "title": "Archival and digital humanities habits", "children": [{"id": "ba08ea60-c7e2-4a81-a2f8-01572141296e", "type": "concept", "title": "metadata and search terms"}, {"id": "5c4e8442-44b6-4aec-b9e8-726a2b38efc5", "type": "concept", "title": "edition comparison"}, {"id": "c0916fc1-896b-4e26-bd66-74d6d4d1e932", "type": "concept", "title": "digital archive citation"}, {"id": "ab7765d2-7e9c-4c9d-8927-9d8a75a86833", "type": "concept", "title": "research ethics and public-domain texts"}], "description": "Students learn how digital archives can support discovery while still requiring careful source criticism."}]}], "dbBacked": true}$aml1json$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'american-literature-i-pre-1865'
);

update public.learning_paths
set
  title = 'American Literature I (Pre-1865)',
  goal = 'American Literature I (Pre-1865)',
  summary = 'American Literature I (Pre-1865) surveys literature in and about North America from Indigenous oral traditions and colonial encounter through Puritanism, revolution, early national print culture, slavery and abolition, Transcendentalism, American Romanticism, women writers, poetry, and antebellum politics. The course treats literature as an archive of contested nation formation: a record of sovereignty, empire, faith, race, gender, labor, environment, citizenship, and literary experiment. Students practice close reading, historical contextualization, archive use, and scholarly argument.',
  data = $aml1json${"slug": "american-literature-i-pre-1865", "title": "American Literature I (Pre-1865)", "description": "American Literature I (Pre-1865) surveys literature in and about North America from Indigenous oral traditions and colonial encounter through Puritanism, revolution, early national print culture, slavery and abolition, Transcendentalism, American Romanticism, women writers, poetry, and antebellum politics. The course treats literature as an archive of contested nation formation: a record of sovereignty, empire, faith, race, gender, labor, environment, citizenship, and literary experiment. Students practice close reading, historical contextualization, archive use, and scholarly argument.", "topics": [{"id": "a4f32190-fe64-49e4-93be-d04de59c9303", "type": "topic", "title": "What Counts as Early American Literature: Archives, Orality, Print, and Periodization", "description": "This opening unit challenges students to ask what American literature is before the United States fully exists. The course begins by treating literature as oral performance, manuscript, sermon, political pamphlet, captivity narrative, newspaper, poetry, fiction, and archive.", "children": [{"id": "da979b28-3423-473d-8073-6eb374193bfa", "type": "subtopic", "title": "Periodization and field boundaries", "children": [{"id": "580e848e-eafb-4620-a1fc-ca15558737cb", "type": "concept", "title": "precontact, colonial, revolutionary, early republic, and antebellum frames"}, {"id": "92618aec-d484-46e3-a410-b65b22e8cc9d", "type": "concept", "title": "British America, Spanish borderlands, Caribbean, and Atlantic contexts"}, {"id": "4f30c03a-e927-4409-b092-6d00e267c1d8", "type": "concept", "title": "nation formation and its exclusions"}, {"id": "bfd03349-c9c8-4725-b545-9247b4d4cc81", "type": "concept", "title": "Civil War as threshold rather than endpoint"}], "description": "Students learn why pre-1865 American literature is not just a march toward a national canon, but a contested field shaped by empire, Indigenous sovereignty, slavery, revolution, and print culture."}, {"id": "8750ac9a-3366-4464-8abc-324cf3272d66", "type": "subtopic", "title": "Archives and textual survival", "children": [{"id": "4b9eb4c0-a221-489d-9e9b-e3e2ddc1ad4d", "type": "concept", "title": "manuscript versus print"}, {"id": "cfa28412-2d1c-47c2-829a-eb890a28d2d3", "type": "concept", "title": "editorial mediation"}, {"id": "78aeb286-1d69-48c0-8895-b32237e33407", "type": "concept", "title": "translation and transcription"}, {"id": "42483584-fecf-460b-a9b2-5d6ddc6f2cc7", "type": "concept", "title": "libraries, archives, and digital collections"}], "description": "The point is to understand that syllabi are built from preserved, edited, translated, and institutionalized materials."}, {"id": "2a4c9e1a-d977-4a9e-966b-475986b7d70b", "type": "subtopic", "title": "Methods for reading early texts", "children": [{"id": "f00be588-2f51-44d1-b8bb-cbbd6c757015", "type": "concept", "title": "close reading"}, {"id": "c7181920-566d-439f-9466-fc15714cbceb", "type": "concept", "title": "historicism"}, {"id": "2f5d47a0-b2f5-46a9-8fc8-a5fa5871adf7", "type": "concept", "title": "book history"}, {"id": "d911f97f-316e-4637-ace0-d3817cb2bc30", "type": "concept", "title": "keywords and conceptual history"}], "description": "Students practice close reading while also attending to genre, audience, material form, and historical pressure."}]}, {"id": "0c8d773b-f777-4144-9129-5f1d3a3c52af", "type": "topic", "title": "Indigenous Oral Traditions, Sovereignty, and Contact Narratives", "description": "This unit centers Indigenous presence before and beyond European colonization. Students approach oral traditions, creation narratives, diplomacy, petitions, and contact accounts as complex literary and political forms.", "children": [{"id": "5a068d74-06a5-492a-aa5e-928e318a8156", "type": "subtopic", "title": "Orality, performance, and translation", "children": [{"id": "5a8ddd6b-81c3-4d4b-bf7a-94251fbb45a1", "type": "concept", "title": "creation and emergence narratives"}, {"id": "3aacec3e-b9ef-4e8e-9339-71495cb805c9", "type": "concept", "title": "story cycles and teaching functions"}, {"id": "9309f718-036e-495c-afbb-bba452c6fe80", "type": "concept", "title": "translation politics"}, {"id": "5e4668c4-2991-45d3-b89b-2cf1a869731d", "type": "concept", "title": "performance context and audience"}], "description": "Students learn that oral traditions are not primitive precursors to literature; they are sophisticated knowledge systems shaped by performance, memory, and community."}, {"id": "e5c5977d-3697-44a1-bcf6-d81cd40f3722", "type": "subtopic", "title": "Contact and colonial encounter", "children": [{"id": "f3f327fd-493e-4706-86e3-c986d4b71fac", "type": "concept", "title": "exploration narratives"}, {"id": "c29f4119-0aba-402b-95c4-bf40bea6e435", "type": "concept", "title": "missionary records"}, {"id": "8f4f5159-8e27-48ae-818a-d9234c72f44a", "type": "concept", "title": "ethnographic framing"}, {"id": "f4d372a5-dc36-4673-a167-2721823285f8", "type": "concept", "title": "reciprocity, misunderstanding, and violence"}], "description": "Students examine how European contact accounts construct the Americas and how Indigenous perspectives resist or redirect those claims."}, {"id": "d7c0bc17-f180-420b-8dbe-d27f1a791e97", "type": "subtopic", "title": "Sovereignty and political writing", "children": [{"id": "cf987968-f77a-4287-b0f3-13c97f6839d2", "type": "concept", "title": "treaty rhetoric"}, {"id": "a2f10d3b-bc1e-460c-821f-ed17a53deaea", "type": "concept", "title": "petition and memorial"}, {"id": "e4857de3-a0b7-481d-b12b-87c7dd7d76f9", "type": "concept", "title": "land, law, and kinship"}, {"id": "51183579-7168-4549-8715-ce9f9c425424", "type": "concept", "title": "survivance and continuity"}], "description": "The goal is to read Indigenous speeches, petitions, and diplomacy as literary acts and assertions of nationhood."}]}, {"id": "d72ba4a7-d4ff-45ac-97e7-ea0c5777101d", "type": "topic", "title": "Colonial Encounters, Exploration, and Settlement Writing", "description": "Students study how colonial writing tried to describe, possess, market, and govern the Americas. The emphasis is on rhetoric, empire, religion, labor, and the unstable relationship between observation and ideology.", "children": [{"id": "b494c22d-37eb-470b-822d-5e98b316776d", "type": "subtopic", "title": "Promotional and exploration writing", "children": [{"id": "e695c911-2d2a-45b2-894a-2a33d428caa1", "type": "concept", "title": "wonder and abundance"}, {"id": "4acbb5db-3b7f-4e48-b018-869b28c8881d", "type": "concept", "title": "mapping and naming"}, {"id": "5e975f63-5968-40b7-a031-4e6f47710852", "type": "concept", "title": "colonial propaganda"}, {"id": "918343fe-f943-498a-881a-dfb8ffd1263d", "type": "concept", "title": "resource extraction and labor"}], "description": "Students learn how travel and settlement texts turned land into a project for investors, monarchs, settlers, and readers abroad."}, {"id": "19d79a80-aef4-4346-8d85-da21a819a274", "type": "subtopic", "title": "Mission, conversion, and cultural conflict", "children": [{"id": "b3c93fe7-ae06-49cb-aef5-40f1db071dfe", "type": "concept", "title": "missionary accounts"}, {"id": "2bff7759-2085-4bc0-9cf2-d278db225c64", "type": "concept", "title": "conversion narratives"}, {"id": "cd06017a-7384-4dda-a595-7ad78d5dda9e", "type": "concept", "title": "biblical typology"}, {"id": "31e9e436-9fa9-4d8d-8881-a5013ac570c5", "type": "concept", "title": "cultural translation"}], "description": "Students examine religious language as both spiritual expression and colonial technology."}, {"id": "9073b366-0ea8-4b83-bc77-cd83760ee547", "type": "subtopic", "title": "Colonial genres and authority", "children": [{"id": "d92eb575-7631-4564-8b0b-dbe7bcf6bd4d", "type": "concept", "title": "eyewitness testimony"}, {"id": "803609db-c53d-4cbf-8f35-76bb4f4b3e30", "type": "concept", "title": "letters and journals"}, {"id": "d3171aa1-7c65-4850-b257-477a71c07ce9", "type": "concept", "title": "legal and administrative documents"}, {"id": "6abea238-9a67-40df-b313-1eb6011658c4", "type": "concept", "title": "ethnographic description"}], "description": "Students learn how authors claim credibility when describing unfamiliar places, peoples, and events."}]}, {"id": "a4b5f11a-d30a-4777-9efe-64e04ba9b2fa", "type": "topic", "title": "Puritan Theology, Captivity Narratives, and New England Plain Style", "description": "This unit examines Puritan writing as a literary system grounded in providence, covenant, typology, discipline, and community anxiety. Students read sermons, poetry, spiritual autobiography, and captivity narratives as crafted forms.", "children": [{"id": "75a8e07d-06e7-459c-8d26-26dc5c9f0f6d", "type": "subtopic", "title": "Puritan worldviews and rhetorical form", "children": [{"id": "19f44ce0-ab98-41d0-bc9e-bfe4f697ac40", "type": "concept", "title": "covenant theology"}, {"id": "90d69879-a2b9-4778-b8cb-7df287e53b5d", "type": "concept", "title": "plain style"}, {"id": "b7664201-f62e-43c5-b0ca-e38b740ab2f4", "type": "concept", "title": "typology"}, {"id": "7983eb57-f0ed-44ba-9d9c-c98d1088bbd0", "type": "concept", "title": "sermon structure"}], "description": "Students learn how theology shapes voice, metaphor, plot, and interpretation in seventeenth-century New England writing."}, {"id": "252c8315-25cd-4a93-bddd-698636e7ebf5", "type": "subtopic", "title": "Spiritual autobiography and self-examination", "children": [{"id": "b7be96dd-a3d3-41bd-83ae-89c32f18afdd", "type": "concept", "title": "conversion narrative"}, {"id": "e9c10484-4cd2-49b1-bde5-f4a58d1e38f4", "type": "concept", "title": "diary and meditation"}, {"id": "b9586bf5-b97b-4463-a90c-f9d2ebc1aa0f", "type": "concept", "title": "sin, grace, and assurance"}, {"id": "15bb809c-0080-4d8b-ab30-3c37215cf9c2", "type": "concept", "title": "communal surveillance"}], "description": "Students see how inwardness becomes literary evidence, especially in conversion and devotional writing."}, {"id": "4b34595f-1c3e-49cd-81a3-b338e1e6cd70", "type": "subtopic", "title": "Captivity and border conflict", "children": [{"id": "689760c0-dd4f-43f7-8b41-8caa0a48ba5f", "type": "concept", "title": "Mary Rowlandson and genre conventions"}, {"id": "e8202d1c-944b-4625-b917-34593f3fe8b3", "type": "concept", "title": "violence and providence"}, {"id": "91587140-1f95-46ee-b23c-938d6c650bc7", "type": "concept", "title": "Indigenous representation"}, {"id": "79bb73e3-4963-4e72-b735-45aadb69fce4", "type": "concept", "title": "gendered authorship and authority"}], "description": "Students analyze captivity narratives as religious testimony, colonial propaganda, trauma narrative, and cross-cultural encounter."}]}, {"id": "7f8cdeb5-7a42-404f-a1c9-ee3ed2fa4add", "type": "topic", "title": "Enlightenment, Republicanism, Revolution, and Founding Rhetorics", "description": "Students move from colonial religious frameworks to Enlightenment argument, political persuasion, autobiography, and revolutionary print culture. The unit asks how literature helps imagine citizens, rights, virtue, and nationhood.", "children": [{"id": "df111e41-e262-4d0b-944f-781fc5d8f069", "type": "subtopic", "title": "Franklin and self-making", "children": [{"id": "2ec0d05a-2018-40e5-b0dc-f9ed1dbe4817", "type": "concept", "title": "virtue charts and self-improvement"}, {"id": "4041fd99-06f2-40b8-a217-c3623dcd94c1", "type": "concept", "title": "print capitalism"}, {"id": "873484b6-0164-4499-8aaa-6b66edb5f6c6", "type": "concept", "title": "wit and persona"}, {"id": "7aad1baa-226f-46bb-96b5-bbad94e968b6", "type": "concept", "title": "republican usefulness"}], "description": "Students read autobiography as a genre of self-fashioning, social mobility, discipline, and public performance."}, {"id": "0b31cfd0-df91-4964-9626-937ec2ad1107", "type": "subtopic", "title": "Revolutionary argument and pamphlet culture", "children": [{"id": "6e26bd85-25ae-4f84-9baf-4cacff3a6476", "type": "concept", "title": "Thomas Paine and plain argument"}, {"id": "9d3c6bfe-2fc0-4921-a173-d94f7efd3058", "type": "concept", "title": "Jefferson and declaration rhetoric"}, {"id": "0991bc2a-8226-4bb3-92e5-7373dacdafab", "type": "concept", "title": "natural rights language"}, {"id": "42f190be-0e24-4ba8-8254-442790e469a9", "type": "concept", "title": "public sphere and persuasion"}], "description": "Students learn how political prose mobilizes readers through logic, emotion, urgency, and shared grievance."}, {"id": "335df844-c93c-49d1-9828-090850276a79", "type": "subtopic", "title": "Contradictions of liberty", "children": [{"id": "628cd968-3c60-4167-af06-3fb76c449a80", "type": "concept", "title": "enslavement and freedom rhetoric"}, {"id": "0ebdb61c-2ec8-464e-935a-e9085502691e", "type": "concept", "title": "women and republican motherhood"}, {"id": "71d9a5af-4ce2-4561-981a-2056122e17c3", "type": "concept", "title": "Indigenous diplomacy"}, {"id": "be6d20e4-ad51-4250-a854-56cb88d086ae", "type": "concept", "title": "property, consent, and exclusion"}], "description": "Students confront how revolutionary ideals coexist with slavery, dispossession, gender hierarchy, and restricted citizenship."}]}, {"id": "7f0bc419-a21a-4714-8097-0d3d6f612e3b", "type": "topic", "title": "Early Republic Print Culture, Sentimental Fiction, and Gothic Beginnings", "description": "This unit treats the early republic as an experimental literary marketplace. Students study novels, newspapers, magazines, seduction plots, and gothic forms as sites where readers debated morality, gender, class, and national identity.", "children": [{"id": "6e7c507d-0d4e-4328-bd2f-d88c784c884e", "type": "subtopic", "title": "Print culture and readership", "children": [{"id": "ebe388d3-0e4a-4b75-b404-a8c5b24a2597", "type": "concept", "title": "newspapers and magazines"}, {"id": "7a8cd400-caf7-4137-9926-2e259620bd42", "type": "concept", "title": "subscription and circulation"}, {"id": "91894202-6430-4b37-8056-9d87335845bd", "type": "concept", "title": "anonymity and pseudonyms"}, {"id": "a02f6a0d-87ae-4ee1-b99e-462fd5ac290b", "type": "concept", "title": "reading publics"}], "description": "Students learn how expanding print networks shaped literary form and public debate."}, {"id": "5de4cc7f-a777-426e-b2fe-12fa0bc15e0e", "type": "subtopic", "title": "Sentimental and seduction fiction", "children": [{"id": "9ce7670a-093c-4df8-ab7d-3127197a5b08", "type": "concept", "title": "The Coquette and Charlotte Temple traditions"}, {"id": "ba43b509-8377-43bb-96a4-1f835b427dee", "type": "concept", "title": "epistolary form"}, {"id": "aff1ef78-e65d-482e-ae31-8ed2b017fec5", "type": "concept", "title": "female readership"}, {"id": "e24f0185-8674-4f70-97da-b57191fa28b0", "type": "concept", "title": "moral pedagogy and pleasure"}], "description": "Students examine how early novels stage questions of virtue, consent, education, reputation, and social control."}, {"id": "5ab6b38a-3c81-49c2-b48f-80cccb767533", "type": "subtopic", "title": "American gothic", "children": [{"id": "8477135a-2022-4ced-922c-964b65de6a7d", "type": "concept", "title": "Charles Brockden Brown"}, {"id": "93e2553a-1bb3-4de1-9821-c2b4faa16696", "type": "concept", "title": "haunting and paranoia"}, {"id": "4008ad91-f053-46b8-8761-d9eda16058ea", "type": "concept", "title": "frontier and city spaces"}, {"id": "78392c64-07af-4690-a419-7d2ae02ea8e0", "type": "concept", "title": "madness, reason, and contagion"}], "description": "Students read gothic fiction as a way of representing national anxiety, violence, secrecy, and unstable authority."}]}, {"id": "b54b5da6-911a-456e-ab23-163a77bb3513", "type": "topic", "title": "Slavery, Abolition, and Black Atlantic Writing", "description": "Students study slavery not as background but as a central condition of early American literary production. The unit foregrounds Black authorship, testimony, abolitionist print networks, and Atlantic circuits of freedom and captivity.", "children": [{"id": "edca53d5-0bf4-418f-bc3c-0ea6b33f753d", "type": "subtopic", "title": "Slave narratives as literary and political form", "children": [{"id": "a38a4b7a-df42-4188-83d6-c5fc1b37145c", "type": "concept", "title": "Frederick Douglass"}, {"id": "f72cd79d-f1ad-4661-ada5-7d6adb3b940d", "type": "concept", "title": "Harriet Jacobs"}, {"id": "312759df-49ff-4f19-9e33-d094bd725ced", "type": "concept", "title": "authenticating documents"}, {"id": "b0228859-0e1e-4e40-bc6d-43f448d9dd12", "type": "concept", "title": "scene of literacy"}], "description": "Students learn how narrators craft authority under hostile conditions and turn life writing into abolitionist evidence."}, {"id": "2686469e-81d5-4dfe-9c6b-65d8ed9c7d51", "type": "subtopic", "title": "Black Atlantic voices", "children": [{"id": "d9bc817e-f66b-47a8-92e4-bde85ebe82bb", "type": "concept", "title": "Phillis Wheatley"}, {"id": "55b25e11-a664-4a89-a310-7048120c9792", "type": "concept", "title": "Olaudah Equiano"}, {"id": "2ac2ebf5-8664-482c-bf78-c73a0e12077f", "type": "concept", "title": "religion and freedom"}, {"id": "d068bb53-6c72-4491-907b-07e221224ad3", "type": "concept", "title": "mobility and diaspora"}], "description": "Students place early African American writing in transatlantic contexts of enslavement, conversion, commerce, and revolution."}, {"id": "35ea030a-b940-4858-a5c2-12205f08befb", "type": "subtopic", "title": "Abolitionist media and rhetoric", "children": [{"id": "d06da0ef-8e9c-4a7f-9969-a6b10cab9974", "type": "concept", "title": "moral suasion"}, {"id": "0ffb7793-f4a9-4bd4-a06d-10c789b0973a", "type": "concept", "title": "visual and print campaigns"}, {"id": "4574d8a9-24df-4ff2-ade4-6435b2203d08", "type": "concept", "title": "women abolitionists"}, {"id": "4580f21d-a1e9-4e04-80ef-2d5e260589af", "type": "concept", "title": "risk, censorship, and violence"}], "description": "Students examine how antislavery writing circulates through speeches, newspapers, poetry, petitions, and reform organizations."}]}, {"id": "5c2ba99d-4af0-444f-9369-f70699ef7dd1", "type": "topic", "title": "Native American and African American Oratory, Petition, and Political Voice", "description": "This unit extends the course beyond canonical genres by treating public address, petitions, memorials, and political documents as literary acts. Students learn how marginalized communities used available forms to speak against law, violence, and exclusion.", "children": [{"id": "73d0476e-a598-4e8e-b382-558ffd306cc9", "type": "subtopic", "title": "Oratory and public address", "children": [{"id": "9426a587-c21b-43ac-bdfc-d4f4899fa9bf", "type": "concept", "title": "delivery and transcription"}, {"id": "024c2989-78d7-4812-9217-0d9263e27327", "type": "concept", "title": "ethos and collective voice"}, {"id": "b07f5ce5-1b64-40a9-a68d-af817ce8ed16", "type": "concept", "title": "mourning and protest"}, {"id": "6595449d-6f71-4f7f-98d7-6a1311edf141", "type": "concept", "title": "religious and civic registers"}], "description": "Students learn to read speeches as performances shaped by occasion, audience, transcription, and power."}, {"id": "a22eb932-eb38-484e-81b6-f3a875277093", "type": "subtopic", "title": "Petition and legal language", "children": [{"id": "98c7b550-3b38-4f44-aa9d-5f8dcb5c7b23", "type": "concept", "title": "petition structure"}, {"id": "fef3cce1-f88b-4b86-b4bf-261fb4dd96b1", "type": "concept", "title": "rights language"}, {"id": "122ab17b-53d9-4c93-a234-a6eee3600cea", "type": "concept", "title": "citizenship claims"}, {"id": "5608b4c2-e4e6-430f-a5e2-c2c9afa22b23", "type": "concept", "title": "archives of dissent"}], "description": "Students study petition as a genre that converts grievance into public record and political claim."}, {"id": "ca0a7d7c-43c3-4d9d-9c7b-c3fe32ff50d4", "type": "subtopic", "title": "Coalition, reform, and counterpublics", "children": [{"id": "0a475fd8-177f-458b-9584-f24e45e7565f", "type": "concept", "title": "Black conventions"}, {"id": "e6cb0dfa-5f05-4309-be1e-acfb0be867c2", "type": "concept", "title": "Indigenous diplomacy"}, {"id": "e6bc16e8-0ae8-4714-8411-b527f37f21b4", "type": "concept", "title": "antislavery networks"}, {"id": "16a221d0-0c9d-42cd-b867-d84b8733ce58", "type": "concept", "title": "newspaper counterpublics"}], "description": "Students explore how writers build communities of readers outside dominant institutions."}]}, {"id": "1e44be66-6d35-4185-b087-48dad93abe86", "type": "topic", "title": "Transcendentalism, Reform, and Environmental Thought", "description": "Students study Transcendentalism as philosophy, literary style, reform culture, and environmental imagination. The unit links Emerson and Thoreau to abolition, education, women’s rights, labor, and nature writing.", "children": [{"id": "a633be48-33cc-49a2-b07c-cd2e89416963", "type": "subtopic", "title": "Emersonian self-reliance and intellectual independence", "children": [{"id": "dc65a18d-3441-4823-85dd-c3a84b9a9376", "type": "concept", "title": "self-reliance"}, {"id": "baa5a1ce-5f5d-47a3-acdb-32d5d000cbad", "type": "concept", "title": "intuition and idealism"}, {"id": "1544f427-e59c-4179-b6c5-be6c6b9f8ef1", "type": "concept", "title": "lecture culture"}, {"id": "25d3a5bd-a806-4120-99c9-2d03b1cf6a2a", "type": "concept", "title": "aphorism and prose style"}], "description": "Students learn how the essay form becomes a vehicle for philosophical provocation and literary experiment."}, {"id": "c29b0081-04a6-4be5-a553-ffc9c32189b6", "type": "subtopic", "title": "Thoreau, nature, and civil disobedience", "children": [{"id": "1f977707-7afb-4a0e-ab33-91789ae25f94", "type": "concept", "title": "Walden and experiment"}, {"id": "de1ab679-497e-4fb2-a51e-617aaa02f7d7", "type": "concept", "title": "walking and observation"}, {"id": "32d9a5ca-8c07-4d4d-a4a2-bdc64caf947a", "type": "concept", "title": "civil disobedience"}, {"id": "2317793a-7433-4f0c-95ca-b95c92df9faa", "type": "concept", "title": "environmental humanities"}], "description": "Students read Thoreau across ecology, economics, ethics, and resistance."}, {"id": "9de310a1-f8e2-4d9b-a661-5a67878a57be", "type": "subtopic", "title": "Reform movements and utopian experiments", "children": [{"id": "7fdf8d6b-368c-44ff-ae35-8401812f4711", "type": "concept", "title": "Brook Farm"}, {"id": "e5f5a5ed-2b36-461a-86c4-e046ecdce608", "type": "concept", "title": "abolition"}, {"id": "c31f18c2-c2a7-4aad-bdaf-bb717b43bf85", "type": "concept", "title": "education reform"}, {"id": "3ef6c438-1b26-4c49-a635-76a0ba152d0f", "type": "concept", "title": "women's rights and labor reform"}], "description": "Students situate Transcendentalist writing in a broader antebellum reform landscape."}]}, {"id": "aba6ae0d-7e11-41a0-af4f-cbe96c5ec717", "type": "topic", "title": "American Romanticism: Poe, Hawthorne, Melville, and Dark National Allegory", "description": "This unit shows how American Romanticism explores obsession, sin, ambiguity, perception, violence, and national guilt. Students learn to connect formal intensity with historical unease.", "children": [{"id": "42f13403-bf83-4c29-900e-946cd96b5304", "type": "subtopic", "title": "Poe and the aesthetics of effect", "children": [{"id": "1d35bd6c-0bba-49eb-8a25-c965db71940d", "type": "concept", "title": "single effect"}, {"id": "d3a376c4-aa21-4501-87d4-e3d4503c9a65", "type": "concept", "title": "unreliable narration"}, {"id": "8324e86b-1bd5-4a60-963c-2c9125fe62c2", "type": "concept", "title": "detective fiction"}, {"id": "6ccd5f27-c51f-4f17-8b5e-9993e6f41e9e", "type": "concept", "title": "sound and lyric intensity"}], "description": "Students examine short fiction and poetry as engineered experiences of fear, compression, rhythm, and unreliability."}, {"id": "14153080-ec75-4dc7-b666-1df71012b3df", "type": "subtopic", "title": "Hawthorne and historical allegory", "children": [{"id": "61f4ac77-4219-4cdd-8c7d-7d89e3767a78", "type": "concept", "title": "romance versus novel"}, {"id": "bab58477-6dc0-42ff-aa27-8ed473624170", "type": "concept", "title": "symbol and ambiguity"}, {"id": "487e9c60-5048-4773-a4a1-1c80a0393474", "type": "concept", "title": "The Scarlet Letter"}, {"id": "0a40705c-1f95-4054-85e3-3bf514654547", "type": "concept", "title": "ancestry and guilt"}], "description": "Students learn how romance allows Hawthorne to revisit Puritanism, secrecy, gender, and moral ambiguity."}, {"id": "e7a446f6-f9fe-4e21-b438-594f99e60f3a", "type": "subtopic", "title": "Melville and epistemological crisis", "children": [{"id": "7841ebe7-c721-4989-9d0a-2a5de6e4d6c4", "type": "concept", "title": "Moby-Dick and encyclopedic form"}, {"id": "49524f4b-25ca-47e0-abd4-61a5070d80df", "type": "concept", "title": "Bartleby and labor"}, {"id": "4509d756-79e9-4638-b6f4-3f3f3aee2fe1", "type": "concept", "title": "race and empire at sea"}, {"id": "94b6d0ae-7435-4d42-9d94-995eaa6ae395", "type": "concept", "title": "irony and narrative instability"}], "description": "Students study Melville’s fiction as a field of philosophical, political, racial, and formal disturbance."}]}, {"id": "7e8695f6-10ff-42e9-bbff-53fc14145ddd", "type": "topic", "title": "American Renaissance, Canon Formation, and Its Revisions", "description": "Students learn why the American Renaissance became a powerful but contested category. The unit treats canon formation as a historical process, then asks how revised canons change the story of American literature.", "children": [{"id": "3308953d-62d6-496a-8e25-81b454bd34b5", "type": "subtopic", "title": "The classic American Renaissance", "children": [{"id": "2b0ae478-441e-4488-9840-81aef56c5ba6", "type": "concept", "title": "Emerson, Thoreau, Hawthorne, Melville, Whitman"}, {"id": "52a0b456-c58a-4c35-b288-78bf1c34d316", "type": "concept", "title": "F. O. Matthiessen and critical history"}, {"id": "9c25a53e-0f7f-4864-9973-5d4146ee25fd", "type": "concept", "title": "democracy and individualism"}, {"id": "4ab65c01-76da-494a-b7bd-3d571c7b1967", "type": "concept", "title": "symbolic depth and national literature"}], "description": "Students identify the authors, myths, and critical arguments that shaped the mid-nineteenth-century canon."}, {"id": "ec2d3d76-a4f3-4599-bccf-8a85d4f0e0ab", "type": "subtopic", "title": "Canon critique and recovery", "children": [{"id": "b5f6916f-1645-4873-aadf-f359b9cd9a28", "type": "concept", "title": "recovery scholarship"}, {"id": "7a540998-f8b3-4f45-adf3-97a252141630", "type": "concept", "title": "anthology politics"}, {"id": "814a6517-a643-42b6-83e5-acc46b80be28", "type": "concept", "title": "genre hierarchy"}, {"id": "441760ad-3688-4c12-9459-a87456201648", "type": "concept", "title": "archives and institutional power"}], "description": "Students learn how feminist, Black, Indigenous, and multiethnic scholarship changed the field."}, {"id": "54620252-a81a-417b-91d0-fcf3ec826499", "type": "subtopic", "title": "Comparative canon building", "children": [{"id": "214af8e0-f74f-4afb-8c11-83d78423a5b0", "type": "concept", "title": "counter-canon exercises"}, {"id": "5bc0916c-2d27-426a-8fdc-4c71310e9756", "type": "concept", "title": "paired readings"}, {"id": "f2f779a4-c1b1-40ab-a3a5-3c5cf7fc3051", "type": "concept", "title": "syllabus design as argument"}, {"id": "3a49a183-c505-47d7-86b2-36e97025717a", "type": "concept", "title": "field keywords"}], "description": "Students practice building alternative literary maps around themes such as slavery, sovereignty, gender, print, ecology, and empire."}]}, {"id": "5443ada6-6c24-4499-8501-9d593382927f", "type": "topic", "title": "Women Writers, Domestic Fiction, Poetry, and Public Authorship", "description": "This unit centers women’s authorship as a major force in early American literature. Students study domestic fiction, poetry, reform writing, letters, and public literary careers.", "children": [{"id": "bc5002a2-a1a9-485c-be98-480090b96bad", "type": "subtopic", "title": "Domestic and sentimental fiction", "children": [{"id": "ff1a63f5-694e-4f4b-aff8-546a9ca58d40", "type": "concept", "title": "Harriet Beecher Stowe"}, {"id": "3bdc4624-d96a-4a0a-a381-c7ddef524e9d", "type": "concept", "title": "Susan Warner and domestic ideology"}, {"id": "c24520ef-6ed2-40a8-bf02-3fac3bddad30", "type": "concept", "title": "sentiment and reform"}, {"id": "c6356386-43e4-4d3f-bec4-ba457a235402", "type": "concept", "title": "home, market, and nation"}], "description": "Students read domestic writing as a serious site of power, pedagogy, race, labor, and national imagination."}, {"id": "51291f52-41ea-476e-aea7-ea873265c10c", "type": "subtopic", "title": "Women poets and literary authority", "children": [{"id": "99a018ee-94f6-4c8e-a9fc-a2e420251e6b", "type": "concept", "title": "Anne Bradstreet"}, {"id": "569acf79-94f2-4add-8e22-e34d478d9868", "type": "concept", "title": "Phillis Wheatley"}, {"id": "f6ff0203-034b-49a2-9196-7a450a7c2cab", "type": "concept", "title": "Emily Dickinson"}, {"id": "20b2abf8-bc27-42b8-b215-b733e5a36d5f", "type": "concept", "title": "manuscript and circulation"}], "description": "Students examine how women poets negotiate publication, privacy, religion, friendship, and formal innovation."}, {"id": "916f4fe2-381c-4b8d-a595-691c37c04fb7", "type": "subtopic", "title": "Gender, authorship, and public reform", "children": [{"id": "6f64c873-9f28-4936-adbd-4539c86ae081", "type": "concept", "title": "abolitionist women"}, {"id": "c94923fd-faf8-4b72-bfd3-96b59832ab09", "type": "concept", "title": "women's rights conventions"}, {"id": "196abf30-467b-4897-bb2a-d24e4d9ad672", "type": "concept", "title": "editorship and periodicals"}, {"id": "5d22ebce-9c86-482e-996a-0c5b7d3c663b", "type": "concept", "title": "respectability and resistance"}], "description": "Students study how women used print and speech to enter debates about slavery, education, labor, and rights."}]}, {"id": "c255e612-2a5a-4f13-a174-bd268b3d76f6", "type": "topic", "title": "Whitman, Dickinson, and the Poetics of Democracy, Selfhood, and Form", "description": "Students close-read two writers whose experiments transformed American poetry. The unit pairs public expansiveness and private compression, asking how form creates ideas of body, nation, faith, death, and self.", "children": [{"id": "0c5aa3f7-09cf-4ec4-a00e-1686f1cb2601", "type": "subtopic", "title": "Whitman and democratic poetics", "children": [{"id": "49338ad7-8d4c-4cd6-8cb2-d99a5324632c", "type": "concept", "title": "Leaves of Grass editions"}, {"id": "ef867923-4178-407e-b2d8-35acc742b7f7", "type": "concept", "title": "catalogue and line"}, {"id": "57a09270-d8b9-480a-8840-d13bbb296332", "type": "concept", "title": "body and sexuality"}, {"id": "27a999d0-333b-4b62-bd80-31d1726d9889", "type": "concept", "title": "war, democracy, and voice"}], "description": "Students examine free verse, catalogues, bodily presence, and the imagined relation between poet and nation."}, {"id": "6b0b46a6-610a-4108-b0ee-ce43e9c5cf80", "type": "subtopic", "title": "Dickinson and lyric compression", "children": [{"id": "61d13215-c6d7-4e52-a0f9-2f9b0505128f", "type": "concept", "title": "manuscript fascicles"}, {"id": "edb9d2f1-295e-4fce-90e6-c66342867bc5", "type": "concept", "title": "meter and hymn form"}, {"id": "5877fc09-00bd-4dfd-9238-c80ad0180318", "type": "concept", "title": "death and belief"}, {"id": "74910bae-9ea7-4854-bd11-e55b146765b2", "type": "concept", "title": "variant words and editorial history"}], "description": "Students learn how Dickinson’s manuscripts, variants, dashes, slant rhyme, and syntax challenge ordinary reading habits."}, {"id": "f98f357c-abae-454b-ab86-f5332626db08", "type": "subtopic", "title": "Comparative poetic method", "children": [{"id": "5f9b27fa-5f58-4695-9c21-fbaa2940995a", "type": "concept", "title": "lineation and stanza"}, {"id": "043d461f-c983-4060-bc3b-116ff7b82c33", "type": "concept", "title": "address and speaker"}, {"id": "8cd3d774-fa2b-46ce-b6f5-b67d116daa50", "type": "concept", "title": "publication history"}, {"id": "742f1d66-b348-48a4-b022-d8b1628a5d6f", "type": "concept", "title": "democracy, privacy, and experiment"}], "description": "Students use Whitman and Dickinson to develop high-level close reading of form as argument."}]}, {"id": "bf8b1c13-88b3-491d-941d-52b2be171a36", "type": "topic", "title": "Antebellum Literature, Sectional Crisis, and Civil War Thresholds", "description": "This unit brings the course to the edge of the Civil War by connecting literary form to sectional conflict, reform urgency, racial violence, and competing ideas of union and freedom.", "children": [{"id": "8844252d-bcdc-44de-8247-c55e011b5d77", "type": "subtopic", "title": "Literature and sectional politics", "children": [{"id": "92a74f88-3ad2-4dbd-934f-c258f61b656f", "type": "concept", "title": "Fugitive Slave Act"}, {"id": "71c3fe18-251f-47b7-b045-b7dd0ab0bfdd", "type": "concept", "title": "Kansas-Nebraska conflict"}, {"id": "ad6e0ff1-a9e2-446e-aec9-d375eefe9e1f", "type": "concept", "title": "proslavery and antislavery rhetoric"}, {"id": "9013b361-8c99-449c-890d-bec907a47a83", "type": "concept", "title": "regional print cultures"}], "description": "Students learn how fiction, poetry, speeches, and newspapers participated in debates over slavery, expansion, and union."}, {"id": "f6911eeb-b7f0-4f5c-8c8f-715cbd70e893", "type": "subtopic", "title": "Civil War thresholds", "children": [{"id": "edf6cfbf-b26a-4037-a217-cfb1cbe4a5ad", "type": "concept", "title": "war poetry beginnings"}, {"id": "ac5b78a0-d116-4688-9605-8bd65432c16b", "type": "concept", "title": "Lincoln and public prose"}, {"id": "725546c5-b403-4a3c-897d-e5ced8cf3151", "type": "concept", "title": "martyrdom and sacrifice"}, {"id": "eba65ba4-8cbf-4f96-bd38-330b1cf37749", "type": "concept", "title": "memory and reconciliation myths"}], "description": "Students trace how prewar literary forms anticipate wartime memory, mourning, and national fracture."}, {"id": "103178d1-0142-42d4-b79f-4c5e957458c8", "type": "subtopic", "title": "Citizenship, race, and futurity", "children": [{"id": "a4bcd69d-e74c-483b-a290-745dcbfded60", "type": "concept", "title": "Dred Scott and legal personhood"}, {"id": "25843b88-7970-4900-9bf8-56b323842e1a", "type": "concept", "title": "Black citizenship claims"}, {"id": "a100df2e-c916-40f4-86f1-e86d606e5cb4", "type": "concept", "title": "Indigenous removal and survival"}, {"id": "73891c3c-6d20-463e-a752-3fc154ba41e9", "type": "concept", "title": "gender and political belonging"}], "description": "Students ask whose futures antebellum literature imagined, denied, or fought to create."}]}, {"id": "a4c85a95-b453-43e4-8a6a-c379bd9ba276", "type": "topic", "title": "Research Methods: Close Reading, Historicism, Archives, and Scholarly Argument", "description": "The final methodological unit gives students the tools to turn literary interest into a rigorous argument. It draws from undergraduate literary study and graduate English methods: bibliography, databases, archives, theory, and ethical citation.", "children": [{"id": "3572d71d-a5be-4bc4-94c2-dc9afadca562", "type": "subtopic", "title": "Close reading and historical evidence", "children": [{"id": "28a62163-366b-4fee-8859-447e6cbf3bbe", "type": "concept", "title": "formal evidence"}, {"id": "8be99f1d-77d4-4339-983d-88a5865d9042", "type": "concept", "title": "historical context"}, {"id": "d6f1ef89-3328-4055-aee1-522f32a4310d", "type": "concept", "title": "genre conventions"}, {"id": "41af3a59-d3da-43fe-b8e3-c0f9828359ad", "type": "concept", "title": "claim-evidence reasoning"}], "description": "Students learn to connect textual details to historically grounded claims without reducing literature to mere illustration."}, {"id": "3882167f-a735-47c5-9ba8-5327bb23d0d6", "type": "subtopic", "title": "Research process and bibliography", "children": [{"id": "f114c10d-14cc-410a-9f85-1ea767a16bb0", "type": "concept", "title": "MLA International Bibliography"}, {"id": "fef391f2-77ee-4b4f-82b6-de3106cd825a", "type": "concept", "title": "JSTOR and Project MUSE"}, {"id": "0e6dd311-fad5-4974-b781-0ad7f33bb9b5", "type": "concept", "title": "annotated bibliography"}, {"id": "5cad3b40-4800-4a8b-89a8-3c92e9c911dc", "type": "concept", "title": "secondary source synthesis"}], "description": "Students practice finding, evaluating, and integrating scholarship in a way that strengthens interpretation."}, {"id": "b2b3684b-45bb-4cf7-9ca3-ed6645b4bab8", "type": "subtopic", "title": "Archival and digital humanities habits", "children": [{"id": "ba08ea60-c7e2-4a81-a2f8-01572141296e", "type": "concept", "title": "metadata and search terms"}, {"id": "5c4e8442-44b6-4aec-b9e8-726a2b38efc5", "type": "concept", "title": "edition comparison"}, {"id": "c0916fc1-896b-4e26-bd66-74d6d4d1e932", "type": "concept", "title": "digital archive citation"}, {"id": "ab7765d2-7e9c-4c9d-8927-9d8a75a86833", "type": "concept", "title": "research ethics and public-domain texts"}], "description": "Students learn how digital archives can support discovery while still requiring careful source criticism."}]}], "dbBacked": true}$aml1json$::jsonb,
