insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('a4f32190-fe64-49e4-93be-d04de59c9303', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', null, 'topic'::public.curated_course_node_type, 'What Counts as Early American Literature: Archives, Orality, Print, and Periodization', 'This opening unit challenges students to ask what American literature is before the United States fully exists. The course begins by treating literature as oral performance, manuscript, sermon, political pamphlet, captivity narrative, newspaper, poetry, fiction, and archive.', 0),
  ('da979b28-3423-473d-8073-6eb374193bfa', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'a4f32190-fe64-49e4-93be-d04de59c9303', 'subtopic'::public.curated_course_node_type, 'Periodization and field boundaries', 'Students learn why pre-1865 American literature is not just a march toward a national canon, but a contested field shaped by empire, Indigenous sovereignty, slavery, revolution, and print culture.', 0),
  ('580e848e-eafb-4620-a1fc-ca15558737cb', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'da979b28-3423-473d-8073-6eb374193bfa', 'concept'::public.curated_course_node_type, 'precontact, colonial, revolutionary, early republic, and antebellum frames', null, 0),
  ('92618aec-d484-46e3-a410-b65b22e8cc9d', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'da979b28-3423-473d-8073-6eb374193bfa', 'concept'::public.curated_course_node_type, 'British America, Spanish borderlands, Caribbean, and Atlantic contexts', null, 1),
  ('4f30c03a-e927-4409-b092-6d00e267c1d8', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'da979b28-3423-473d-8073-6eb374193bfa', 'concept'::public.curated_course_node_type, 'nation formation and its exclusions', null, 2),
  ('bfd03349-c9c8-4725-b545-9247b4d4cc81', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'da979b28-3423-473d-8073-6eb374193bfa', 'concept'::public.curated_course_node_type, 'Civil War as threshold rather than endpoint', null, 3),
  ('8750ac9a-3366-4464-8abc-324cf3272d66', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'a4f32190-fe64-49e4-93be-d04de59c9303', 'subtopic'::public.curated_course_node_type, 'Archives and textual survival', 'The point is to understand that syllabi are built from preserved, edited, translated, and institutionalized materials.', 1),
