  ('78aeb286-1d69-48c0-8895-b32237e33407', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '8750ac9a-3366-4464-8abc-324cf3272d66', 'concept'::public.curated_course_node_type, 'translation and transcription', null, 2),
  ('42483584-fecf-460b-a9b2-5d6ddc6f2cc7', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '8750ac9a-3366-4464-8abc-324cf3272d66', 'concept'::public.curated_course_node_type, 'libraries, archives, and digital collections', null, 3),
  ('2a4c9e1a-d977-4a9e-966b-475986b7d70b', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'a4f32190-fe64-49e4-93be-d04de59c9303', 'subtopic'::public.curated_course_node_type, 'Methods for reading early texts', 'Students practice close reading while also attending to genre, audience, material form, and historical pressure.', 2),
  ('f00be588-2f51-44d1-b8bb-cbbd6c757015', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '2a4c9e1a-d977-4a9e-966b-475986b7d70b', 'concept'::public.curated_course_node_type, 'close reading', null, 0),
