  ('d911f97f-316e-4637-ace0-d3817cb2bc30', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '2a4c9e1a-d977-4a9e-966b-475986b7d70b', 'concept'::public.curated_course_node_type, 'keywords and conceptual history', null, 3),
  ('0c8d773b-f777-4144-9129-5f1d3a3c52af', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', null, 'topic'::public.curated_course_node_type, 'Indigenous Oral Traditions, Sovereignty, and Contact Narratives', 'This unit centers Indigenous presence before and beyond European colonization. Students approach oral traditions, creation narratives, diplomacy, petitions, and contact accounts as complex literary and political forms.', 1),
  ('5a068d74-06a5-492a-aa5e-928e318a8156', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '0c8d773b-f777-4144-9129-5f1d3a3c52af', 'subtopic'::public.curated_course_node_type, 'Orality, performance, and translation', 'Students learn that oral traditions are not primitive precursors to literature; they are sophisticated knowledge systems shaped by performance, memory, and community.', 0),
  ('5a8ddd6b-81c3-4d4b-bf7a-94251fbb45a1', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '5a068d74-06a5-492a-aa5e-928e318a8156', 'concept'::public.curated_course_node_type, 'creation and emergence narratives', null, 0),
  ('3aacec3e-b9ef-4e8e-9339-71495cb805c9', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '5a068d74-06a5-492a-aa5e-928e318a8156', 'concept'::public.curated_course_node_type, 'story cycles and teaching functions', null, 1),
  ('9309f718-036e-495c-afbb-bba452c6fe80', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '5a068d74-06a5-492a-aa5e-928e318a8156', 'concept'::public.curated_course_node_type, 'translation politics', null, 2),
  ('5e4668c4-2991-45d3-b89b-2cf1a869731d', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '5a068d74-06a5-492a-aa5e-928e318a8156', 'concept'::public.curated_course_node_type, 'performance context and audience', null, 3),
  ('e5c5977d-3697-44a1-bcf6-d81cd40f3722', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '0c8d773b-f777-4144-9129-5f1d3a3c52af', 'subtopic'::public.curated_course_node_type, 'Contact and colonial encounter', 'Students examine how European contact accounts construct the Americas and how Indigenous perspectives resist or redirect those claims.', 1),
  ('f3f327fd-493e-4706-86e3-c986d4b71fac', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'e5c5977d-3697-44a1-bcf6-d81cd40f3722', 'concept'::public.curated_course_node_type, 'exploration narratives', null, 0),
