  ('8f4f5159-8e27-48ae-818a-d9234c72f44a', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'e5c5977d-3697-44a1-bcf6-d81cd40f3722', 'concept'::public.curated_course_node_type, 'ethnographic framing', null, 2),
  ('f4d372a5-dc36-4673-a167-2721823285f8', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'e5c5977d-3697-44a1-bcf6-d81cd40f3722', 'concept'::public.curated_course_node_type, 'reciprocity, misunderstanding, and violence', null, 3),
  ('d7c0bc17-f180-420b-8dbe-d27f1a791e97', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '0c8d773b-f777-4144-9129-5f1d3a3c52af', 'subtopic'::public.curated_course_node_type, 'Sovereignty and political writing', 'The goal is to read Indigenous speeches, petitions, and diplomacy as literary acts and assertions of nationhood.', 2),
  ('cf987968-f77a-4287-b0f3-13c97f6839d2', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'd7c0bc17-f180-420b-8dbe-d27f1a791e97', 'concept'::public.curated_course_node_type, 'treaty rhetoric', null, 0),
  ('a2f10d3b-bc1e-460c-821f-ed17a53deaea', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'd7c0bc17-f180-420b-8dbe-d27f1a791e97', 'concept'::public.curated_course_node_type, 'petition and memorial', null, 1),
  ('e4857de3-a0b7-481d-b12b-87c7dd7d76f9', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'd7c0bc17-f180-420b-8dbe-d27f1a791e97', 'concept'::public.curated_course_node_type, 'land, law, and kinship', null, 2),
  ('51183579-7168-4549-8715-ce9f9c425424', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'd7c0bc17-f180-420b-8dbe-d27f1a791e97', 'concept'::public.curated_course_node_type, 'survivance and continuity', null, 3),
  ('d72ba4a7-d4ff-45ac-97e7-ea0c5777101d', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', null, 'topic'::public.curated_course_node_type, 'Colonial Encounters, Exploration, and Settlement Writing', 'Students study how colonial writing tried to describe, possess, market, and govern the Americas. The emphasis is on rhetoric, empire, religion, labor, and the unstable relationship between observation and ideology.', 2),
  ('b494c22d-37eb-470b-822d-5e98b316776d', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'd72ba4a7-d4ff-45ac-97e7-ea0c5777101d', 'subtopic'::public.curated_course_node_type, 'Promotional and exploration writing', 'Students learn how travel and settlement texts turned land into a project for investors, monarchs, settlers, and readers abroad.', 0),
  ('e695c911-2d2a-45b2-894a-2a33d428caa1', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'b494c22d-37eb-470b-822d-5e98b316776d', 'concept'::public.curated_course_node_type, 'wonder and abundance', null, 0),
