  ('19d79a80-aef4-4346-8d85-da21a819a274', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'd72ba4a7-d4ff-45ac-97e7-ea0c5777101d', 'subtopic'::public.curated_course_node_type, 'Mission, conversion, and cultural conflict', 'Students examine religious language as both spiritual expression and colonial technology.', 1),
