  ('d3171aa1-7c65-4850-b257-477a71c07ce9', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '9073b366-0ea8-4b83-bc77-cd83760ee547', 'concept'::public.curated_course_node_type, 'legal and administrative documents', null, 2),
  ('6abea238-9a67-40df-b313-1eb6011658c4', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '9073b366-0ea8-4b83-bc77-cd83760ee547', 'concept'::public.curated_course_node_type, 'ethnographic description', null, 3),
  ('a4b5f11a-d30a-4777-9efe-64e04ba9b2fa', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', null, 'topic'::public.curated_course_node_type, 'Puritan Theology, Captivity Narratives, and New England Plain Style', 'This unit examines Puritan writing as a literary system grounded in providence, covenant, typology, discipline, and community anxiety. Students read sermons, poetry, spiritual autobiography, and captivity narratives as crafted forms.', 3),
  ('75a8e07d-06e7-459c-8d26-26dc5c9f0f6d', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'a4b5f11a-d30a-4777-9efe-64e04ba9b2fa', 'subtopic'::public.curated_course_node_type, 'Puritan worldviews and rhetorical form', 'Students learn how theology shapes voice, metaphor, plot, and interpretation in seventeenth-century New England writing.', 0),
