  ('7983eb57-f0ed-44ba-9d9c-c98d1088bbd0', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '75a8e07d-06e7-459c-8d26-26dc5c9f0f6d', 'concept'::public.curated_course_node_type, 'sermon structure', null, 3),
  ('252c8315-25cd-4a93-bddd-698636e7ebf5', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'a4b5f11a-d30a-4777-9efe-64e04ba9b2fa', 'subtopic'::public.curated_course_node_type, 'Spiritual autobiography and self-examination', 'Students see how inwardness becomes literary evidence, especially in conversion and devotional writing.', 1),
  ('b7be96dd-a3d3-41bd-83ae-89c32f18afdd', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '252c8315-25cd-4a93-bddd-698636e7ebf5', 'concept'::public.curated_course_node_type, 'conversion narrative', null, 0),
