  ('b9586bf5-b97b-4463-a90c-f9d2ebc1aa0f', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '252c8315-25cd-4a93-bddd-698636e7ebf5', 'concept'::public.curated_course_node_type, 'sin, grace, and assurance', null, 2),
  ('15bb809c-0080-4d8b-ab30-3c37215cf9c2', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '252c8315-25cd-4a93-bddd-698636e7ebf5', 'concept'::public.curated_course_node_type, 'communal surveillance', null, 3),
