  ('689760c0-dd4f-43f7-8b41-8caa0a48ba5f', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '4b34595f-1c3e-49cd-81a3-b338e1e6cd70', 'concept'::public.curated_course_node_type, 'Mary Rowlandson and genre conventions', null, 0),
