  ('91587140-1f95-46ee-b23c-938d6c650bc7', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '4b34595f-1c3e-49cd-81a3-b338e1e6cd70', 'concept'::public.curated_course_node_type, 'Indigenous representation', null, 2),
  ('79bb73e3-4963-4e72-b735-45aadb69fce4', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '4b34595f-1c3e-49cd-81a3-b338e1e6cd70', 'concept'::public.curated_course_node_type, 'gendered authorship and authority', null, 3),
  ('7f8cdeb5-7a42-404f-a1c9-ee3ed2fa4add', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', null, 'topic'::public.curated_course_node_type, 'Enlightenment, Republicanism, Revolution, and Founding Rhetorics', 'Students move from colonial religious frameworks to Enlightenment argument, political persuasion, autobiography, and revolutionary print culture. The unit asks how literature helps imagine citizens, rights, virtue, and nationhood.', 4),
