  ('7f0bc419-a21a-4714-8097-0d3d6f612e3b', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', null, 'topic'::public.curated_course_node_type, 'Early Republic Print Culture, Sentimental Fiction, and Gothic Beginnings', 'This unit treats the early republic as an experimental literary marketplace. Students study novels, newspapers, magazines, seduction plots, and gothic forms as sites where readers debated morality, gender, class, and national identity.', 5),
  ('6e7c507d-0d4e-4328-bd2f-d88c784c884e', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '7f0bc419-a21a-4714-8097-0d3d6f612e3b', 'subtopic'::public.curated_course_node_type, 'Print culture and readership', 'Students learn how expanding print networks shaped literary form and public debate.', 0),
