  ('8477135a-2022-4ced-922c-964b65de6a7d', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '5ab6b38a-3c81-49c2-b48f-80cccb767533', 'concept'::public.curated_course_node_type, 'Charles Brockden Brown', null, 0),
