  ('78392c64-07af-4690-a419-7d2ae02ea8e0', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '5ab6b38a-3c81-49c2-b48f-80cccb767533', 'concept'::public.curated_course_node_type, 'madness, reason, and contagion', null, 3),
  ('b54b5da6-911a-456e-ab23-163a77bb3513', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', null, 'topic'::public.curated_course_node_type, 'Slavery, Abolition, and Black Atlantic Writing', 'Students study slavery not as background but as a central condition of early American literary production. The unit foregrounds Black authorship, testimony, abolitionist print networks, and Atlantic circuits of freedom and captivity.', 6),
  ('edca53d5-0bf4-418f-bc3c-0ea6b33f753d', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'b54b5da6-911a-456e-ab23-163a77bb3513', 'subtopic'::public.curated_course_node_type, 'Slave narratives as literary and political form', 'Students learn how narrators craft authority under hostile conditions and turn life writing into abolitionist evidence.', 0),
  ('a38a4b7a-df42-4188-83d6-c5fc1b37145c', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'edca53d5-0bf4-418f-bc3c-0ea6b33f753d', 'concept'::public.curated_course_node_type, 'Frederick Douglass', null, 0),
