  ('5c2ba99d-4af0-444f-9369-f70699ef7dd1', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', null, 'topic'::public.curated_course_node_type, 'Native American and African American Oratory, Petition, and Political Voice', 'This unit extends the course beyond canonical genres by treating public address, petitions, memorials, and political documents as literary acts. Students learn how marginalized communities used available forms to speak against law, violence, and exclusion.', 7),
