  ('0c5aa3f7-09cf-4ec4-a00e-1686f1cb2601', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'c255e612-2a5a-4f13-a174-bd268b3d76f6', 'subtopic'::public.curated_course_node_type, 'Whitman and democratic poetics', 'Students examine free verse, catalogues, bodily presence, and the imagined relation between poet and nation.', 0),
  ('49338ad7-8d4c-4cd6-8cb2-d99a5324632c', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', '0c5aa3f7-09cf-4ec4-a00e-1686f1cb2601', 'concept'::public.curated_course_node_type, 'Leaves of Grass editions', null, 0),
