  ('6b0b46a6-610a-4108-b0ee-ce43e9c5cf80', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'c255e612-2a5a-4f13-a174-bd268b3d76f6', 'subtopic'::public.curated_course_node_type, 'Dickinson and lyric compression', 'Students learn how Dickinson’s manuscripts, variants, dashes, slant rhyme, and syntax challenge ordinary reading habits.', 1),
