  ('bf8b1c13-88b3-491d-941d-52b2be171a36', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', null, 'topic'::public.curated_course_node_type, 'Antebellum Literature, Sectional Crisis, and Civil War Thresholds', 'This unit brings the course to the edge of the Civil War by connecting literary form to sectional conflict, reform urgency, racial violence, and competing ideas of union and freedom.', 13),
  ('8844252d-bcdc-44de-8247-c55e011b5d77', 'c7d8e9f0-1a2b-4d36-9f56-6a7b8c9d0e66', 'bf8b1c13-88b3-491d-941d-52b2be171a36', 'subtopic'::public.curated_course_node_type, 'Literature and sectional politics', 'Students learn how fiction, poetry, speeches, and newspapers participated in debates over slavery, expansion, and union.', 0),
